import React, { useState } from 'react';
import styled from 'styled-components';
import TextBox from '../../components/common/TextBox';
import Button from '../../components/common/Button';

const Container = styled.div`
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: ${props => props.theme.colors.background};
  padding: ${props => props.theme.spacing.xl};
`;

const FormContainer = styled.div`
  background: ${props => props.theme.colors.white};
  padding: ${props => props.theme.spacing.xl};
  border-radius: ${props => props.theme.borderRadius.large};
  width: 100%;
  max-width: 400px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const Title = styled.h1`
  color: ${props => props.theme.colors.secondary};
  text-align: center;
  margin-bottom: ${props => props.theme.spacing.lg};
  font-size: ${props => props.theme.typography.fontSizes.xxlarge};
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: ${props => props.theme.spacing.md};
`;

const ToggleText = styled.p`
  text-align: center;
  margin-top: ${props => props.theme.spacing.md};
  color: ${props => props.theme.colors.gray.dark};
  font-size: ${props => props.theme.typography.fontSizes.small};

  span {
    color: ${props => props.theme.colors.primary};
    cursor: pointer;
    font-weight: 500;
  }
`;

const UserTypeToggle = styled.div`
  display: flex;
  gap: ${props => props.theme.spacing.sm};
  margin-bottom: ${props => props.theme.spacing.md};
`;

const Register: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [userType, setUserType] = useState<'customer' | 'business'>('customer');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Handle registration logic here
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  return (
    <Container>
      <FormContainer>
        <Title>Create Account</Title>
        <Form onSubmit={handleSubmit}>
          <UserTypeToggle>
            <Button
              variant={userType === 'customer' ? 'primary' : 'outline'}
              onClick={() => setUserType('customer')}
              fullWidth
            >
              Customer
            </Button>
            <Button
              variant={userType === 'business' ? 'primary' : 'outline'}
              onClick={() => setUserType('business')}
              fullWidth
            >
              Business
            </Button>
          </UserTypeToggle>

          <TextBox
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            name="name"
          />
          <TextBox
            type="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            name="email"
          />
          <TextBox
            type="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            name="password"
          />
          <TextBox
            type="password"
            placeholder="Confirm Password"
            value={formData.confirmPassword}
            onChange={handleChange}
            name="confirmPassword"
          />
          <Button onClick={() => handleSubmit(new Event('submit') as React.FormEvent)} fullWidth>
            Register
          </Button>
        </Form>

        <ToggleText>
          Already have an account?{' '}
          <span>Login</span>
        </ToggleText>
      </FormContainer>
    </Container>
  );
};

export default Register;
